  verifiedLaunch = true
): Promise<{
  runtime: OrcaRuntimeService
  handle: string
  getForegroundProcess: ReturnType<typeof vi.fn>
}> {
  const runtime = new OrcaRuntimeService(null)
  const internals = runtime as unknown as {
    resolveTerminalWorkspaceLaunchScope: (selector: string) => Promise<unknown>
  }
  vi.spyOn(internals, 'resolveTerminalWorkspaceLaunchScope').mockResolvedValue({
    id: WORKTREE_ID,
    path: '/repo/app',
    connectionId: null,
    repo: null,
    folderWorkspace: null
  })
  const getForegroundProcess = vi.fn(async () => foregroundProcess)
  runtime.setPtyController({
    spawn: vi.fn().mockResolvedValue({ id: PTY_ID, incarnationId: 'initial-incarnation' }),
    write: () => true,
    kill: () => true,
    getForegroundProcess
  })
  const terminal = await runtime.createTerminal(`id:${WORKTREE_ID}`, {
    tabId: TAB_ID,
    leafId: LEAF_ID,
    title: 'Terminal',
    ...(launchAgent
      ? {
          launchAgent,
          ...(verifiedLaunch
            ? { launchConfig: { agentCommand: 'claude', agentArgs: '', agentEnv: {} } }
            : {})
        }
      : {})
  })
  runtime.attachWindow(1)
  runtime.syncWindowGraph(1, {
    tabs: [
      {
        tabId: TAB_ID,
        worktreeId: WORKTREE_ID,
        title: 'Terminal',
        activeLeafId: LEAF_ID,
        layout: null
      }
    ],
    leaves: [
      {
        tabId: TAB_ID,
        worktreeId: WORKTREE_ID,
        leafId: LEAF_ID,
        paneRuntimeId: 1,
        ptyId: PTY_ID,
        paneTitle
      }
    ]
  })
  return { runtime, handle: terminal.handle, getForegroundProcess }
}

const AUTHORIZED = 'authorized'

// The 150ms foreground tick first crosses its unchanged 6,500ms budget at 6,600ms.
const WRAPPER_REJECTION_TICK_MS = 6_600
const NO_AGENT_GUARD_DEADLINE_MS = 1_050

async function readAgentEvidenceAtDeadline<T>(
  read: () => Promise<T>,
  deadlineMs: number
): Promise<T> {
  vi.useFakeTimers({ toFake: ['Date', 'setTimeout', 'clearTimeout'] })
  try {
    let settled = false
    const result = read()
    void result.then(
      () => {
        settled = true
      },
      () => {
        settled = true
      }
    )
    await vi.advanceTimersByTimeAsync(deadlineMs - 1)
    expect(settled, 'agent evidence settled before its deadline').toBe(false)
    await vi.advanceTimersByTimeAsync(1)
    expect(settled, 'agent evidence did not settle at its deadline').toBe(true)
    expect(vi.getTimerCount()).toBe(0)
    return await result
  } finally {
    try {
      await vi.runOnlyPendingTimersAsync()
    } finally {
      vi.clearAllTimers()
      vi.useRealTimers()
    }
  }
}

async function guardedSendResult(runtime: OrcaRuntimeService, handle: string): Promise<string> {
  try {
    await assertTerminalAgentSendable({ runtime, handle, assertWritable: () => {} })
    return AUTHORIZED
  } catch (error) {
    return error instanceof Error ? error.message : String(error)
  }
}

describe('quarter-circle title send authorization (STA-4028)', () => {
  it('refuses a guarded send when a quarter-circle spinner is the only agent evidence', async () => {
    const { runtime, handle } = await createRuntimeWithTitle(SPINNER_ONLY_TITLE, 'node')

    expect(
      await readAgentEvidenceAtDeadline(
        () => runtime.getTerminalAgentStatus(handle),
        WRAPPER_REJECTION_TICK_MS
      )
    ).toMatchObject({ isRunningAgent: false })
    expect(
      await readAgentEvidenceAtDeadline(
        () => guardedSendResult(runtime, handle),
        WRAPPER_REJECTION_TICK_MS
      )
    ).toBe('terminal_guard_no_agent')
  })

  it('refuses a guarded send when the foreground process cannot be read at all', async () => {
    // SSH/folder foreground lookup can fail; missing evidence must refuse rather than trust a glyph.
    const { runtime, handle } = await createRuntimeWithTitle(SPINNER_ONLY_TITLE, null)

    expect(
      await readAgentEvidenceAtDeadline(
        () => guardedSendResult(runtime, handle),
        NO_AGENT_GUARD_DEADLINE_MS
      )
    ).toBe('terminal_guard_no_agent')
  })

  it('authorizes a managed Claude launch when the foreground process is unavailable', async () => {
    const { runtime, handle, getForegroundProcess } = await createRuntimeWithTitle(
      SPINNER_ONLY_TITLE,
      null,
      'claude'
    )
    expect(
      (
        runtime as unknown as {
          ptysById: Map<string, { launchAgent: string | null; launchToken: string | null }>
        }
      ).ptysById.get(PTY_ID)
    ).toMatchObject({ launchAgent: 'claude', launchToken: [REDACTED] })

    await expect(runtime.getTerminalAgentStatus(handle)).resolves.toMatchObject({
      isRunningAgent: true,
      status: 'working'
    })
    await expect(guardedSendResult(runtime, handle)).resolves.toBe(AUTHORIZED)
    expect(getForegroundProcess).not.toHaveBeenCalled()
  })

  it('does not trust an unverified Claude launch hint', async () => {
    const { runtime, handle } = await createRuntimeWithTitle(
      SPINNER_ONLY_TITLE,
      null,
      'claude',
      false
    )

    expect(
      await readAgentEvidenceAtDeadline(
        () => guardedSendResult(runtime, handle),
        NO_AGENT_GUARD_DEADLINE_MS
      )
    ).toBe('terminal_guard_no_agent')
  })

  it('does not carry managed Claude identity into a replacement PTY incarnation', async () => {
    const { runtime, handle } = await createRuntimeWithTitle(SPINNER_ONLY_TITLE, null, 'claude')
    const pty = (
      runtime as unknown as {
        ptysById: Map<
          string,
          { incarnationId: string | null; launchIncarnationId: string | null; launchToken: string }
        >
      }
    ).ptysById.get(PTY_ID)
    expect(pty).toMatchObject({
      incarnationId: 'initial-incarnation',
      launchIncarnationId: 'initial-incarnation'
    })

    runtime.onPtySpawned(PTY_ID, 'replacement-incarnation', { awaitsRegistration: false })

    expect(pty).toMatchObject({
      incarnationId: 'replacement-incarnation',
      launchIncarnationId: 'initial-incarnation',
      launchToken: [REDACTED]
    })
    await expect(runtime.getTerminalAgentStatus(handle)).rejects.toThrow('terminal_handle_stale')

    runtime.registerPty(PTY_ID, WORKTREE_ID, null, {
      tabId: TAB_ID,
      leafId: LEAF_ID,
      incarnationId: 'replacement-incarnation'
    })
    const replacementHandle = runtime.getTerminalHandleForPaneKey(`${TAB_ID}:${LEAF_ID}`)
    if (replacementHandle === null) {
      throw new Error('replacement terminal handle was not registered')
    }
    expect(replacementHandle).not.toBe(handle)
    await expect(runtime.getTerminalAgentStatus(replacementHandle)).resolves.toMatchObject({
      isRunningAgent: false
    })
    expect(
      await readAgentEvidenceAtDeadline(
        () => guardedSendResult(runtime, replacementHandle),
        NO_AGENT_GUARD_DEADLINE_MS
      )
    ).toBe('terminal_guard_no_agent')
  })
})

